        onClick={onToggle}
        onKeyDown={handleKeyDown}
        aria-expanded={isExpanded}
        aria-controls={`feature-tasks-${feature.id}`}
        className="flex cursor-pointer items-center gap-3 px-4 py-2.5 transition-colors hover:bg-surface-subtle focus-visible:outline focus-visible:outline-2 focus-visible:outline-primary"
        style={{ minWidth: totalWidth }}
      >
        <ChevronRight
          className={
            "h-4 w-4 shrink-0 text-text-muted transition-transform duration-150 " +
            (isExpanded ? "rotate-90" : "")
          }
          aria-hidden="true"
        />
        <span className="min-w-0 flex-1 truncate text-sm font-semibold text-text-primary">
          {feature.title || feature.id}
        </span>
        {nextAction && (
          <span className="shrink-0 truncate text-xs text-text-muted" title={nextAction}>
            → {nextAction}
          </span>
        )}
        <FeatureStatusPill status={feature.featureStatus} />
        <span className="shrink-0 text-xs text-text-muted">
          {doneTasks}/{totalTasks}
        </span>
        <SegmentBar tasks={feature.tasks} />
      </div>

      {/* Expanded task grid — 7 equal columns */}
      {isExpanded && (
        <div
          id={`feature-tasks-${feature.id}`}
          className="flex border-t border-border"
          style={{ minWidth: totalWidth }}
        >
          {STATUS_COLUMNS.map((col) => {
            const colTasks = tasksByStatus[col.key] ?? [];
            return (
              <div
                key={col.key}
                className="flex flex-col gap-2 border-r border-border p-2 last:border-r-0"
                style={{ minWidth: columnWidth, width: columnWidth }}
                role="group"
                aria-label={`${col.label} tasks for ${feature.title || feature.id}`}
              >
                {colTasks.map((task) => (
                  <TaskCard
                    key={task.id}
                    task={task}
                    featureId={feature.id}
                    featureTitle={feature.title || feature.id}
                    onSelect={onSelectTask}
                  />
                ))}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
